function validate([nums]) {
  if (nums.length < 3 || nums.length > 100000) return 'nums needs 3 to 10^5 values.';
  if (nums.some((v) => v < -1000000000 || v > 1000000000)) return 'Each value is between -10^9 and 10^9.';
  return null;
}

