function makeArrayPositive(nums) {
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + nums[i];
  }
  let operations = 0;
  let lastReplaced = -1;
  let maxPrefix = -Infinity;
  for (let end = 2; end < n; end++) {
    const start = end - 2;
    if (start > lastReplaced) {
      maxPrefix = Math.max(maxPrefix, prefix[start]);
    }
    if (prefix[end + 1] <= maxPrefix) {
      operations++;
      lastReplaced = end;
      maxPrefix = -Infinity;
    }
  }
  return operations;
}

