function makeArrayPositive(nums) {
  // Try every set of positions: overwrite them with 10^12, which outweighs the rest of any small array,
  // and test the definition on every subarray of length 3 or more.
  const n = nums.length;
  let best = Infinity;
  for (let mask = 0; mask < 2 ** n; mask++) {
    const chosen = nums.map((_, i) => Math.floor(mask / 2 ** i) % 2 === 1);
    const changed = nums.map((value, i) => (chosen[i] ? 1e12 : value));
    let positive = true;
    for (let a = 0; a < n && positive; a++) {
      let sum = 0;
      for (let b = a; b < n; b++) {
        sum += changed[b];
        if (b - a >= 2 && sum <= 0) {
          positive = false;
          break;
        }
      }
    }
    if (positive) best = Math.min(best, chosen.filter(Boolean).length);
  }
  return best;
}

