function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(3, 9);
  const mode = pick(0, 2);
  if (mode === 0) return [Array.from({ length: n }, () => pick(-4, 4))];
  if (mode === 1) {
    // Mostly positive values with occasional dips, so bad subarrays are rarer and spread out.
    const scale = size === 'large' ? pick(1, 100000000) : 1;
    const dips = 0.02 + rand() * 0.28;
    return [Array.from({ length: n }, () => (rand() < dips ? -pick(1, 10) : pick(1, 4)) * scale)];
  }
  return [Array.from({ length: n }, () => pick(-1000000000, 1000000000))];
}
